  homeMenu=new ImageButton(context);homeMenu.setImageResource(R.drawable.ic_menu);homeMenu.setImageTintList(android.content.res.ColorStateList.valueOf(0xFF252525));homeMenu.setContentDescription(context.getString(R.string.open_menu));homeMenu.setBackgroundColor(Color.TRANSPARENT);homeMenu.setPadding(dp(12),dp(12),dp(12),dp(12));LayoutParams menuPosition=new LayoutParams(dp(48),dp(48));menuPosition.gravity=Gravity.CENTER_HORIZONTAL;addView(homeMenu,menuPosition);homeMenu.setOnClickListener(view->actions.openMenu());
  rebuildHome();
  body=new LinearLayout(context);body.setOrientation(VERTICAL);addView(body,new LayoutParams(-1,-1));back=new ImageButton(context);back.setImageResource(R.drawable.ic_back);back.setContentDescription("Tilbage");back.setBackgroundColor(Color.TRANSPARENT);navigation=new LinearLayout(context);navigation.setGravity(Gravity.CENTER_VERTICAL);body.addView(navigation,new LayoutParams(-1,-2));navigation.addView(back,new LayoutParams(dp(48),dp(48)));back.setOnClickListener(view->back());
  title=text("",20);title.setTypeface(null,Typeface.BOLD);title.setCompoundDrawablePadding(MediaListStyle.iconGap(title));title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);navigation.addView(title,new LayoutParams(0,-2,1));
  kind=new RadioGroup(context);kind.setOrientation(RadioGroup.HORIZONTAL);String[] kinds={"TV","Film","Serier"};for(int i=0;i<kinds.length;i++){RadioButton option=new RadioButton(context);option.setId(View.generateViewId());option.setText(kinds[i]);option.setTextColor(Color.WHITE);option.setTextSize(16);kind.addView(option,new RadioGroup.LayoutParams(0,-2,1));}((RadioButton)kind.getChildAt(0)).setChecked(true);body.addView(kind,new LayoutParams(-1,-2));kind.setOnCheckedChangeListener((group,id)->{for(int i=0;i<group.getChildCount();i++)if(group.getChildAt(i).getId()==id)selectedKind=i;refresh();});
