 void rebuildHome(){home.removeAllViews();for(String name:actions.library().favoriteHomeOrder){if(actions.library().hiddenHomeButtons.contains(name))continue;int streaming=Arrays.asList("TV","Film","Serier").indexOf(name);int icon=streaming>=0?(streaming==0?0:streaming+3):Arrays.asList(FavoriteLists.NAMES).indexOf(name);Button button=new FavoriteHomeButton(getContext(),name,icon);LayoutParams params=new LayoutParams(-1,-2);params.topMargin=dp(12);home.addView(button,params);button.setOnClickListener(view->{if(streaming>=0){selectStreamingKind(streaming);showList("Streaming");}else showList(name);});button.setOnLongClickListener(view->{int index=actions.library().favoriteHomeOrder.indexOf(name);PopupMenu menu=new PopupMenu(getContext(),view);menu.getMenu().add("Flyt op").setEnabled(index>0).setOnMenuItemClickListener(item->{if(actions.save(()->actions.library().moveFavoriteHome(name,-1)))rebuildHome();return true;});menu.getMenu().add("Flyt ned").setEnabled(index>=0&&index<actions.library().favoriteHomeOrder.size()-1).setOnMenuItemClickListener(item->{if(actions.save(()->actions.library().moveFavoriteHome(name,1)))rebuildHome();return true;});menu.show();return true;});}}
 private int dp(int size){return Math.round(size*getResources().getDisplayMetrics().density);}
 private TextView text(String label,int size){TextView view=new TextView(getContext());view.setText(label);view.setTextColor(Color.WHITE);view.setTextSize(size);return view;}
 void selectStreamingKind(int value){if(value>=0&&value<kind.getChildCount())kind.check(kind.getChildAt(value).getId());}
 void showHome(){rebuildHome();generation++;category="";folders.clear();home.setVisibility(VISIBLE);homeScroll.setVisibility(VISIBLE);homeMenu.setVisibility(VISIBLE);body.setVisibility(GONE);actions.navigation(false);}
 void showList(String name){generation++;category=name;folders.clear();home.setVisibility(GONE);homeScroll.setVisibility(GONE);homeMenu.setVisibility(GONE);body.setVisibility(VISIBLE);search.setText("");refresh();}
 boolean canBack(){return !category.isEmpty();}
 void back(){if(!folders.isEmpty()){folders.removeLast();search.setText("");if(!folders.isEmpty())loadFolder();else{generation++;refresh();}}else showHome();}
 private List<LocalMedia> queue(){List<LocalMedia> queue=new ArrayList<>();for(FavoriteLists.Item item:visible)if(item.file!=null)queue.add(item.file);return queue;}
 private void loadFolder(){int request=++generation;LocalMedia folder=folders.peekLast();children.clear();refresh();PcloudAccount account=actions.library().pcloud;worker.execute(()->{try{List<LocalMedia> result;if(PcloudDocument.is(folder.uri)){WebDavClient client=new WebDavClient(account);try{result=new ArrayList<>();for(WebDavClient.Entry entry:client.list(PcloudDocument.url(account,folder.uri)))result.add(entry.media(account));}finally{client.cancel();}}else result=LocalMedia.children(getContext(),folder);Collections.sort(result,NaturalNameOrder.MEDIA);post(()->{if(!closed&&request==generation){children.clear();children.addAll(result);refresh();}});}catch(Exception error){post(()->{if(!closed&&request==generation)Toast.makeText(getContext(),"Mappen kunne ikke åbnes.",Toast.LENGTH_LONG).show();});}});}
 void refresh(){if(list==null||category.isEmpty())return;boolean folder=!folders.isEmpty();navigation.setVisibility(folder?VISIBLE:GONE);back.setVisibility(folder?VISIBLE:GONE);title.setText(folder?folders.peekLast().displayName():category.equals("Streaming")?new String[]{"TV","Film","Serier"}[selectedKind]:category);title.setCompoundDrawablesWithIntrinsicBounds(folder?R.drawable.ic_folder:0,0,0,0);kind.setVisibility(GONE);search.setVisibility(folder||category.equals("Podcast")||category.equals("Musik")?VISIBLE:GONE);String query=search.getText().toString().trim().toLowerCase(Locale.ROOT);visible.clear();List<FavoriteLists.Item> entries=new ArrayList<>();if(folder){for(LocalMedia child:children)entries.add(FavoriteLists.of(child));}else entries=FavoriteLists.items(actions.library(),category);for(FavoriteLists.Item item:entries){if(!folder&&category.equals("Streaming")&&item.kind(actions.library()).ordinal()!=selectedKind)continue;if(item.name().toLowerCase(Locale.ROOT).contains(query))visible.add(item);}adapter.notifyDataSetChanged();actions.navigation(true);}
 void programmeChanged(){adapter.notifyDataSetChanged();}
 void close(){closed=true;generation++;worker.shutdownNow();removeCallbacks(tick);}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();post(tick);}
 @Override protected void onDetachedFromWindow(){removeCallbacks(tick);super.onDetachedFromWindow();}
